        return 0                      # no primes exist below 2 or 3
    is_composite = [False] * n         # tracks which numbers have been crossed out
    count = 0
    for pnum in range(2, n):
        if not is_composite[pnum]:
            count += 1                    # pnum was never crossed out, so it is prime
            for multiple in range(2 * pnum, n, pnum):
                is_composite[multiple] = True  # cross out every multiple of this prime
    return count


