def count_primes(n):
    if n < 3:
        return 0                      # no primes exist below 2 or 3
    is_composite = [False] * n         # tracks which numbers have been crossed out
    pnum = 2
    while pnum * pnum < n:
        if not is_composite[pnum]:
            for multiple in range(pnum * pnum, n, pnum):
                is_composite[multiple] = True  # start crossing out from p squared, not 2p
        pnum += 1
    return sum(1 for i in range(2, n) if not is_composite[i])  # count everything never crossed out


if __name__ == "__main__":
    n = 10
    print(count_primes(n))

